// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Inventory_Assessment_dispatch_coordination_process_inventory_assessment_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment)
  }

  /** helper function to set the values of all input ports.
   * @param pending_request payload for data port pending_request
   * @param inventory_evidence payload for data port inventory_evidence
   */
  def put_concrete_inputs(pending_request : Factory_Dispatch_Coordinator.Pending_Request_View.Type,
                          inventory_evidence : Factory_Dispatch_Coordinator.Inventory_Sample): Unit = {
    put_pending_request(pending_request)
    put_inventory_evidence(inventory_evidence)
  }


  /** helper function to check Inventory_Assessment_dispatch_coordination_process_inventory_assessment's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param inventory_finding method that will be called with the value of the outgoing data
   *        port 'inventory_finding'.
   */
  def check_concrete_output(inventory_finding: Factory_Dispatch_Coordinator.Inventory_Finding.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val inventory_findingValue: Factory_Dispatch_Coordinator.Inventory_Finding.Type = get_inventory_finding().get
    if(!inventory_finding(inventory_findingValue)) {
      testFailures = testFailures :+ st"'inventory_finding' did not match expected: value of the outgoing data port is ${inventory_findingValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_pending_request(value : Factory_Dispatch_Coordinator.Pending_Request_View.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment.operational_api.pending_request_Id, Factory_Dispatch_Coordinator.Pending_Request_View_Payload(value))
  }

  // setter for in DataPort
  def put_inventory_evidence(value : Factory_Dispatch_Coordinator.Inventory_Sample): Unit = {
    Art.insertInInfrastructurePort(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment.operational_api.inventory_evidence_Id, Factory_Dispatch_Coordinator.Inventory_Sample_Payload(value))
  }

  // getter for out DataPort
  def get_inventory_finding(): Option[Factory_Dispatch_Coordinator.Inventory_Finding.Type] = {
    val value: Option[Factory_Dispatch_Coordinator.Inventory_Finding.Type] = get_inventory_finding_payload() match {
      case Some(Factory_Dispatch_Coordinator.Inventory_Finding_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port inventory_finding.  Expecting 'Factory_Dispatch_Coordinator.Inventory_Finding_Payload' but received ${v}")
      case _ => None[Factory_Dispatch_Coordinator.Inventory_Finding.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_inventory_finding_payload(): Option[Factory_Dispatch_Coordinator.Inventory_Finding_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Finished_Product_Dispatch_Coordinator_System_Instance_dispatch_coordination_process_inventory_assessment.initialization_api.inventory_finding_Id).asInstanceOf[Option[Factory_Dispatch_Coordinator.Inventory_Finding_Payload]]
  }

}
